// Extract input data
const inputData = $input.first().json;
const recipients = inputData.recipients || [];
const messageContent = inputData.message?.content || '';
const isFlash = inputData.message?.isFlash || false;
const branchId = inputData.filters?.branch || null;
const sentBy = inputData.sentBy || 'system';

// Sanitize mobile number function
function sanitizeMobileNumber(phone) {
  if (!phone) return null;

  // Remove all non-numeric characters
  let cleaned = phone.toString().replace(/\D/g, '');

  // Convert to +639 format
  if (cleaned.startsWith('63')) {
    cleaned = '+63' + cleaned.substring(2);
  } else if (cleaned.startsWith('0')) {
    cleaned = '+63' + cleaned.substring(1);
  } else if (cleaned.startsWith('9') && cleaned.length === 10) {
    cleaned = '+63' + cleaned;
  } else if (!cleaned.startsWith('+')) {
    cleaned = '+63' + cleaned;
  }

  // Validate final format
  if (cleaned.startsWith('+63') && cleaned.length === 13) {
    return cleaned;
  }

  return null;
}

// Prepare items for insertion
const items = [];
const messageGroupId = `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

for (const recipient of recipients) {
  const sanitizedPhone = sanitizeMobileNumber(recipient.phone);

  items.push({
    json: {
      status: sanitizedPhone ? 'pending' : 'failed',
      content: messageContent,
      phone_number: sanitizedPhone || recipient.phone,
      message_type: isFlash ? 'flash' : 'normal',
      direction: 'out',
      module_id: 'mod1',
      message_group_id: messageGroupId,
      branch_id: branchId,
      recipient_name: recipient.name,
      recipient_id: recipient.id,
      is_flash: isFlash,
      sent_by: sentBy,
      error_message: !sanitizedPhone ? 'Invalid phone number format' : null,
      created_at: new Date().toISOString()
    }
  });
}

return items;
